/*{
  "DESCRIPTION": "Gently falling snow with twinkling lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "skyColor", "TYPE": "color", "DEFAULT": [0.0, 0.1, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float snowFlake(vec2 uv, vec2 center, float size) {
  float dist = length(uv - center);
  return smoothstep(size * 1.5, size * 0.3, dist);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  vec3 sky = skyColor.rgb;

  vec3 snow = vec3(0.0);

  for (int i = 0; i < 16; i++) {
    float fi = float(i);
    vec2 seed = vec2(fi * 0.3, fi * 0.7);

    float xOffset = hash(seed) * 2.0 - 1.0;
    float yPhase = mod(TIME * speed * 0.3 + hash(seed + vec2(1.0, 0.0)), 1.5);
    float y = 1.0 - yPhase;

    float x = fract(uv.x + xOffset + TIME * speed * 0.05);
    float twinkle = 0.5 + 0.5 * sin(TIME * 3.0 + fi * 0.5);
    float flake = snowFlake(uv, vec2(x, y), 0.02) * twinkle;

    snow += snowColor.rgb * flake * density;
  }

  vec3 final = mix(sky, snow, min(snow, 1.0));
  gl_FragColor = vec4(final, 1.0);
}

/*{
  "DESCRIPTION": "Fire rising from the bottom with flickering flames",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorBase", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorTip", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "height", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.8 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float isLine = step(RENDERSIZE.y, 1.5);
  float animPos = uv.x - TIME * speed * 0.25;
  float vertPos = mix(uv.y, uv.x, isLine);

  float flame = 0.0;
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float wave = sin(animPos * 3.14159 + fi * 0.785) * 0.5 + 0.5;
    float freq = 2.0 + fi * 0.5;
    float noise = sin(animPos * freq + fi * 1.234 + TIME * speed) * 0.5 + 0.5;
    float flicker = sin(TIME * speed * 2.0 + fi) * 0.3 + 0.7;

    float yOffset = wave * 0.3 + noise * 0.2;
    float firePos = vertPos - yOffset;
    float falloff = exp(-firePos * firePos * 8.0) * flicker;
    flame += falloff;
  }

  flame = clamp(flame * 0.5, 0.0, 1.0);
  float fireFade = smoothstep(height + 0.2, 0.0, vertPos);
  flame *= fireFade;

  vec3 fireColor = mix(colorBase.rgb, colorTip.rgb, flame);
  gl_FragColor = vec4(fireColor, 1.0);
}

/*{
  "DESCRIPTION": "Candy cane stripes scrolling diagonally across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripeWidth", "TYPE": "float", "MIN": 0.02, "MAX": 0.3, "DEFAULT": 0.1 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float diagonal = uv.x + uv.y - TIME * speed * 0.5;
  float pattern = fract(diagonal / stripeWidth);
  float stripe = step(0.5, pattern);

  vec3 color = mix(colorA.rgb, colorB.rgb, stripe);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Smooth color wash that fades between palette colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float t = mod(TIME * speed * 0.5 + uv.x * scale, float(NUMCOLORS));
  int colorIndex = int(floor(t));
  float blend = fract(t);

  vec3 col1 = vec3(0.5);
  vec3 col2 = vec3(0.5);

  if (colorIndex == 0 && NUMCOLORS >= 1) {
    col1 = isf_color(0).rgb;
  } else if (colorIndex == 1 && NUMCOLORS >= 2) {
    col1 = isf_color(1).rgb;
  } else if (colorIndex == 2 && NUMCOLORS >= 3) {
    col1 = isf_color(2).rgb;
  } else if (colorIndex == 3 && NUMCOLORS >= 4) {
    col1 = isf_color(3).rgb;
  }

  int nextIndex = int(mod(float(colorIndex + 1), float(NUMCOLORS)));
  if (nextIndex == 0 && NUMCOLORS >= 1) {
    col2 = isf_color(0).rgb;
  } else if (nextIndex == 1 && NUMCOLORS >= 2) {
    col2 = isf_color(1).rgb;
  } else if (nextIndex == 2 && NUMCOLORS >= 3) {
    col2 = isf_color(2).rgb;
  } else if (nextIndex == 3 && NUMCOLORS >= 4) {
    col2 = isf_color(3).rgb;
  }

  vec3 finalColor = mix(col1, col2, smoothstep(0.0, 1.0, blend));

  gl_FragColor = vec4(finalColor, 1.0);
}

