/*{
  "DESCRIPTION": "Twinkling stars scattered across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "starColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "backgroundColor", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.1, 1.0] },
    { "NAME": "twinkleSpeed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "starDensity", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.8 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  vec2 gridPos = uv * starDensity * 8.0;
  vec2 gridCell = floor(gridPos);
  vec2 cellUv = fract(gridPos);

  float starSeed = hash(gridCell);
  float starThreshold = 0.7;

  vec3 finalColor = backgroundColor.rgb;

  if (starSeed > starThreshold) {
    vec2 starCenter = vec2(0.5, 0.5);
    float distToCenter = length(cellUv - starCenter);

    if (distToCenter < 0.35) {
      float twinkle = abs(sin(TIME * twinkleSpeed + starSeed * 6.28));
      float brightness = smoothstep(0.35, 0.0, distToCenter) * (0.4 + twinkle * 0.6);
      finalColor = mix(finalColor, starColor.rgb, brightness);
    }
  }

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Colored light chase running horizontally along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "spacing", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.2 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float roofY = uv.y;
  if (RENDERSIZE.y < 2.0) {
    roofY = uv.x;
  }

  float chasePos = fract((uv.x - TIME * speed * 0.25) / spacing);
  float beacon = smoothstep(0.15, 0.0, abs(chasePos - 0.5));

  vec3 light = mix(colorA.rgb, colorB.rgb, step(0.5, chasePos));
  light = mix(light, colorC.rgb, step(0.75, chasePos));

  vec3 finalColor = light * beacon;

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma effect with animated vortex patterns",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 2.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;
  vec2 center = vec2(0.5, 0.5);
  vec2 pos = uv - center;

  float angle = atan(pos.y, pos.x);
  float radius = length(pos);

  float time = TIME * speed * 0.5;

  float spiral1 = sin(angle * 3.0 + time - radius * scale * 4.0);
  float spiral2 = cos(angle * 2.0 + time * 0.7 + radius * scale * 3.0);
  float spiral3 = sin(angle + time * 1.3 - radius * scale * 2.0);

  float pattern = spiral1 * 0.4 + spiral2 * 0.35 + spiral3 * 0.25;
  pattern += sin(radius * scale * 6.0 - time) * 0.3;

  float intensity = smoothstep(0.0, 1.0, fract(pattern));

  vec3 color = mix(colorA.rgb, colorB.rgb, fract(spiral1 * 0.5 + time));
  color = mix(color, colorC.rgb, fract(spiral2 * 0.5));

  color *= intensity;

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Rainbow colors sweep horizontally across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float sweep = mod(uv.x - TIME * speed * 0.5 + uv.y * width, 1.0);

  vec3 rgb;
  if (sweep < 0.166667) {
    rgb = mix(vec3(1.0, 0.0, 0.0), vec3(1.0, 0.5, 0.0), fract(sweep * 6.0));
  } else if (sweep < 0.333333) {
    rgb = mix(vec3(1.0, 0.5, 0.0), vec3(1.0, 1.0, 0.0), fract(sweep * 6.0));
  } else if (sweep < 0.5) {
    rgb = mix(vec3(1.0, 1.0, 0.0), vec3(0.0, 1.0, 0.0), fract(sweep * 6.0));
  } else if (sweep < 0.666667) {
    rgb = mix(vec3(0.0, 1.0, 0.0), vec3(0.0, 0.0, 1.0), fract(sweep * 6.0));
  } else if (sweep < 0.833333) {
    rgb = mix(vec3(0.0, 0.0, 1.0), vec3(0.75, 0.0, 1.0), fract(sweep * 6.0));
  } else {
    rgb = mix(vec3(0.75, 0.0, 1.0), vec3(1.0, 0.0, 0.0), fract(sweep * 6.0));
  }

  gl_FragColor = vec4(rgb, 1.0);
}

/*{
  "DESCRIPTION": "Lights pulse in rhythm to a steady beat",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.8 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;
  float beat = sin(TIME * speed * 3.14159) * 0.5 + 0.5;
  float pulse = pow(beat, sharpness);
  vec3 color = mix(colorA.rgb, colorB.rgb, uv.x);
  gl_FragColor = vec4(color * pulse, 1.0);
}

/*{
  "DESCRIPTION": "American flag waving with stars and stripes",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveAmount", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.3 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float waveY = sin(uv.x * 6.28318 + TIME * speed) * waveAmount * 0.2;
  float distortedY = uv.y + waveY;

  vec3 color = vec3(0.0);

  if (distortedY < 0.0 || distortedY > 1.0) {
    color = vec3(0.0);
  } else if (distortedY < 0.077) {
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedY < 0.154) {
    color = vec3(1.0, 1.0, 1.0);
  } else if (distortedY < 0.231) {
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedY < 0.308) {
    color = vec3(1.0, 1.0, 1.0);
  } else if (distortedY < 0.385) {
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedY < 0.462) {
    color = vec3(1.0, 1.0, 1.0);
  } else if (distortedY < 0.539) {
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedY < 0.616) {
    color = vec3(1.0, 1.0, 1.0);
  } else if (distortedY < 0.693) {
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedY < 0.77) {
    color = vec3(1.0, 1.0, 1.0);
  } else if (distortedY < 0.847) {
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedY < 0.924) {
    color = vec3(1.0, 1.0, 1.0);
  } else {
    color = vec3(1.0, 0.0, 0.0);
  }

  if (uv.x < 0.4 && distortedY < 0.539) {
    color = vec3(0.0, 0.0, 0.4);
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "fogColor", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float fogX = fract(uv.x + TIME * speed * 0.3);
  float fogY = uv.y;

  float fog = sin(fogX * 6.28318 + TIME * speed * 0.5) * 0.5 + 0.5;
  fog *= sin(fogY * 3.14159 + TIME * speed * 0.2) * 0.5 + 0.5;
  fog = pow(fog, 1.0 - density * 0.8);

  vec3 finalColor = fogColor.rgb * fog;
  float alpha = fog * density;

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "A spinning tunnel that pulls you forward into its depths",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "spirals", "TYPE": "float", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord - vec2(0.5);
  float angle = atan(uv.y, uv.x);
  float radius = length(uv);

  float depth = mod(TIME * speed * 0.5 - radius * 3.0, 1.0);
  float spiral = mod(angle * spirals / 6.28318530718 + TIME * speed * 0.3, 1.0);

  float innerRing = smoothstep(0.05, 0.0, abs(radius - 0.2));
  float spiralStripe = smoothstep(0.08, 0.0, abs(spiral - 0.5));
  float depthRing = smoothstep(0.1, 0.0, abs(depth - 0.5));

  float brightness = max(spiralStripe * depthRing, innerRing);
  brightness *= (1.0 - radius * 1.5);
  brightness = max(brightness, 0.0);

  vec3 col = mix(colorA.rgb, colorB.rgb, spiral);
  gl_FragColor = vec4(col * brightness, 1.0);
}

/*{
  "DESCRIPTION": "Ocean waves rolling across the display with foam crests",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorDeep", "TYPE": "color", "DEFAULT": [0.0, 0.2, 0.6, 1.0] },
    { "NAME": "colorShallow", "TYPE": "color", "DEFAULT": [0.0, 0.8, 1.0, 1.0] },
    { "NAME": "colorFoam", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "wavelength", "TYPE": "float", "MIN": 0.1, "MAX": 3.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float isLine = step(RENDERSIZE.y, 1.5);
  float animCoord = mix(uv.x, uv.y, isLine);

  float wave1 = sin((animCoord - TIME * speed * 0.5) * wavelength * 6.28318) * 0.5 + 0.5;
  float wave2 = sin((animCoord * 0.7 - TIME * speed * 0.35) * wavelength * 6.28318) * 0.5 + 0.5;
  float wave3 = sin((animCoord * 1.3 - TIME * speed * 0.65) * wavelength * 6.28318) * 0.5 + 0.5;

  float waveHeight = (wave1 + wave2 * 0.6 + wave3 * 0.4) / 2.1;

  float foamCrest = smoothstep(0.7, 0.95, waveHeight);
  float shallowBand = smoothstep(0.3, 0.6, waveHeight);

  vec3 color = mix(colorDeep.rgb, colorShallow.rgb, shallowBand);
  color = mix(color, colorFoam.rgb, foamCrest);

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Slow lava lamp blobs that drift and morph through the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 }
  ]
}*/

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  float t = TIME * speed * 0.3;

  float blob1 = noise(uv.x * scale + t * 0.7 + noise(t * 0.3) * 2.0);
  blob1 += noise(uv.x * scale * 0.5 + t * 0.5 + 10.0) * 0.5;
  blob1 = smoothstep(0.3, 0.7, blob1);

  float blob2 = noise(uv.x * scale * 0.8 + t * 0.4 + 100.0 + noise(t * 0.2 + 50.0) * 2.0);
  blob2 += noise(uv.x * scale * 0.3 + t * 0.6 + 200.0) * 0.5;
  blob2 = smoothstep(0.2, 0.8, blob2);

  float blend = sin(t * 0.4) * 0.5 + 0.5;
  float combined = mix(blob1, blob2, blend);
  combined = smoothstep(0.2, 0.9, combined);

  vec3 color = mix(colorA.rgb, colorB.rgb, sin(t * 0.2) * 0.5 + 0.5);
  color *= combined;

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Alternating flashes between two colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
