float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  vec3 col = vec3(0.0);

  float t = TIME * speed;

  for (int i = 0; i < 16; i++) {
    float fi = float(i);
    vec2 gridPos = floor(uv * density) + vec2(mod(fi, 4.0), floor(fi / 4.0)) * 0.25;
    float seed = hash(gridPos);

    float dropTime = mod(t + seed * 6.283, 3.0);
