    col += mix(colorA.rgb, colorB.rgb, 0.5) * ripple * 0.6;
    col += colorB.rgb * dropBright * 0.8;
  }

  col = clamp(col, 0.0, 1.0);
  gl_FragColor = vec4(col, 1.0);
